CREATE ROLE fieldforce_app NOLOGIN;
CREATE TABLE companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, settings jsonb NOT NULL DEFAULT '{"brand":"FieldForce Pro","currency":"EGP","timezone":"Africa/Cairo","annualPlans":true,"requireGps":false,"activityDays":30,"primaryColor":"#176b55"}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies, name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, employee_code text, phone text, supervisor_id uuid, active boolean NOT NULL DEFAULT true, language text NOT NULL DEFAULT 'ar', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,id), FOREIGN KEY(company_id,supervisor_id) REFERENCES users(company_id,id));
CREATE TABLE roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies, name text NOT NULL, UNIQUE(company_id,name), UNIQUE(company_id,id));
CREATE TABLE permissions (key text PRIMARY KEY);
CREATE TABLE role_permissions (role_id uuid REFERENCES roles ON DELETE CASCADE, permission text REFERENCES permissions, PRIMARY KEY(role_id,permission));
CREATE TABLE user_roles (company_id uuid NOT NULL, user_id uuid NOT NULL, role_id uuid NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id), FOREIGN KEY(company_id,role_id) REFERENCES roles(company_id,id));
CREATE TABLE regions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies, name text NOT NULL, UNIQUE(company_id,id), UNIQUE(company_id,name));
CREATE TABLE areas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies, region_id uuid NOT NULL, name text NOT NULL, UNIQUE(company_id,id), UNIQUE(company_id,name), FOREIGN KEY(company_id,region_id) REFERENCES regions(company_id,id));
CREATE TABLE teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies, name text NOT NULL, supervisor_id uuid, UNIQUE(company_id,id), FOREIGN KEY(company_id,supervisor_id) REFERENCES users(company_id,id));
CREATE TABLE user_areas (company_id uuid NOT NULL, user_id uuid NOT NULL, area_id uuid NOT NULL, PRIMARY KEY(user_id,area_id), FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id), FOREIGN KEY(company_id,area_id) REFERENCES areas(company_id,id));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE password_resets (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE login_attempts (key text PRIMARY KEY, attempts int NOT NULL DEFAULT 1, started_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies, code text NOT NULL DEFAULT ('CUS-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), name text NOT NULL, name_en text, type text NOT NULL, phone text NOT NULL, email text, area_id uuid NOT NULL, representative_id uuid, classification text NOT NULL DEFAULT 'B' CHECK(classification IN ('A','B','C','VIP')), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','suspended','prospect')), address text, city text, contact_person text, whatsapp text, latitude numeric(10,7), longitude numeric(10,7), credit_limit numeric(16,2) CHECK(credit_limit>=0), tax_id text, notes text, details jsonb NOT NULL DEFAULT '{}', created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, UNIQUE(company_id,id), UNIQUE(company_id,code), FOREIGN KEY(company_id,area_id) REFERENCES areas(company_id,id), FOREIGN KEY(company_id,representative_id) REFERENCES users(company_id,id), FOREIGN KEY(company_id,created_by) REFERENCES users(company_id,id));
CREATE TABLE customer_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,customer_id uuid NOT NULL,old_rep uuid,new_rep uuid,old_area uuid,new_area uuid,changed_by uuid NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(company_id,customer_id) REFERENCES customers(company_id,id));
CREATE TABLE leave_types (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies,name text NOT NULL,paid boolean NOT NULL DEFAULT true,UNIQUE(company_id,id),UNIQUE(company_id,name));
CREATE TABLE leave_balances (company_id uuid NOT NULL,user_id uuid NOT NULL,leave_type_id uuid NOT NULL,year int NOT NULL,opening numeric(6,2) NOT NULL CHECK(opening>=0),used numeric(6,2) NOT NULL DEFAULT 0 CHECK(used>=0),PRIMARY KEY(user_id,leave_type_id,year),FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id),FOREIGN KEY(company_id,leave_type_id) REFERENCES leave_types(company_id,id));
CREATE TABLE approval_workflows (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies,module text NOT NULL CHECK(module IN ('visits','collections','invoices','plans','leaves')),name text NOT NULL,steps jsonb NOT NULL CHECK(jsonb_array_length(steps)>0),UNIQUE(company_id,module),UNIQUE(company_id,id));
CREATE TABLE approval_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies,module text NOT NULL,entity_id uuid NOT NULL,submitted_by uuid NOT NULL,area_id uuid,steps jsonb NOT NULL,current_step int NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,module,entity_id),UNIQUE(company_id,id),FOREIGN KEY(company_id,submitted_by) REFERENCES users(company_id,id),FOREIGN KEY(company_id,area_id) REFERENCES areas(company_id,id));
CREATE TABLE approval_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,request_id uuid NOT NULL,step int NOT NULL,approver_id uuid NOT NULL,decision text NOT NULL CHECK(decision IN ('approved','rejected')),comment text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,step),FOREIGN KEY(company_id,request_id) REFERENCES approval_requests(company_id,id),FOREIGN KEY(company_id,approver_id) REFERENCES users(company_id,id));
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,user_id uuid NOT NULL,title text NOT NULL,body text,link text,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id));
CREATE TABLE attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies,module text NOT NULL,entity_id uuid NOT NULL,uploaded_by uuid NOT NULL,name text NOT NULL,mime text NOT NULL,size int NOT NULL CHECK(size>0 AND size<=10485760),storage_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies,user_id uuid,action text NOT NULL,entity text NOT NULL,entity_id uuid,old_values jsonb,new_values jsonb,ip text,created_at timestamptz NOT NULL DEFAULT now());

CREATE FUNCTION app_company() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.company',true),'')::uuid $$;
CREATE FUNCTION app_user() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user',true),'')::uuid $$;
CREATE FUNCTION app_can(p text) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT coalesce(current_setting('app.permissions',true)::jsonb ? p,false) $$;
CREATE FUNCTION app_area(a uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT app_can('customers.view_all') OR coalesce(current_setting('app.areas',true)::jsonb ? a::text,false) $$;
CREATE FUNCTION app_scope(m text, u uuid, a uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT (u=app_user() AND (app_can(m||'.view_own') OR app_can(m||'.create'))) OR (app_can(m||'.view_all') AND (a IS NULL OR app_area(a))) OR (app_can(m||'.view_team') AND app_area(a)) $$;
CREATE INDEX customers_area_idx ON customers(company_id,area_id);
CREATE INDEX customers_rep_idx ON customers(company_id,representative_id);
CREATE INDEX approvals_pending_idx ON approval_requests(company_id,status,created_at);
CREATE INDEX notifications_user_idx ON notifications(company_id,user_id,read_at);
CREATE INDEX audit_time_idx ON audit_logs(company_id,created_at DESC);
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
